import { ref } from 'vue';
import { defineStore } from 'pinia';
import type * as CRUDL from '../crudl-client';

function generateStorageKey(type: string, id: string): string {
  return `${type}#${id}`;
}

export const useLocalCrudlStore = defineStore('localCrudl', () => {
  const items = ref(new Map<string, CRUDL.Item>());

  async function createItem(item: Partial<CRUDL.Item>): Promise<CRUDL.Item> {
      const itemId = item.id || crypto.randomUUID();
      const itemType = item.type;
      const itemParentType = item.parentType || 'USER';
      const itemParentId = item.parentId || 'USER_ID'; // Simulated single user

      const now = new Date().toISOString();
      const meta: CRUDL.ItemMeta = {
        createdAt: now,
        updatedAt: now,
        version: 1,
      };

      const newItem: CRUDL.Item = {
        type: itemType,
        id: itemId,
        parentType: itemParentType,
        parentId: itemParentId,
        data: item?.data || {},
        meta,
        user: 'USER_ID', // Associate with the simulated single user
      };

      const storageKey = generateStorageKey(itemType, itemId);
      if (items.value.has(storageKey)) {
        throw new Error(`Item with key ${storageKey} already exists`);
      }

      items.value.set(storageKey, newItem);
      return newItem;
    }

    async function readItem(type: string, id: string): Promise<CRUDL.Item> {
      const storageKey = generateStorageKey(type, id);
      const item = items.value.get(storageKey);
      if (!item) throw new Error(`Item with key ${storageKey} not found`);
      else return item;
    }

    async function updateItem(
      type: string,
      id: string,
      data: Record<string, any>,
      options?: { merge?: boolean }
    ): Promise<CRUDL.Item> {
      const storageKey = generateStorageKey(type, id);
      const existingItem = items.value.get(storageKey);
      if (!existingItem) throw new Error(`Item with key ${storageKey} not found`);

      const updatedData = options?.merge ? { ...existingItem.data, ...data } : data;

      const currentMeta = existingItem.meta || { createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), version: 0 };

      const newMeta: CRUDL.ItemMeta = {
        ...currentMeta,
        updatedAt: new Date().toISOString(),
        version: currentMeta.version + 1,
      };

      const updatedItem: CRUDL.Item = {
        ...existingItem,
        data: updatedData,
        meta: newMeta,
      };

      items.value.set(storageKey, updatedItem);
      return updatedItem;
    }

    async function deleteItem(type: string, id: string): Promise<void> {
      const storageKey = generateStorageKey(type, id);
      if (!items.value.has(storageKey)) {
        throw new Error(`Item with key ${storageKey} not found for delete`);
      }
      items.value.delete(storageKey);
      return Promise.resolve();
    }

    async function listChildren(
      parentType: string,
      parentId: string,
      childType='all',
      options?: { limit?: number; nextPage?: string }
    ): Promise<CRUDL.QueryResponse> {
      const limit = options?.limit || 50;
      const startIndex = options?.nextPage ? parseInt(options.nextPage, 10) : 0;

      const allMatchingChildren: CRUDL.Item[] = [];
      for (const item of items.value.values()) { //TODO confirm shape of items and why we are using .values() here
        if (item.parentType === parentType && item.parentId === parentId) {
          if (childType && childType !== 'all' && item.type !== childType) {
            continue;
          }
          allMatchingChildren.push(item);
        }
      }

      const paginatedItems = allMatchingChildren.slice(startIndex, startIndex + limit);
      let newNextPage: string | undefined = undefined;

      if (startIndex + limit < allMatchingChildren.length) {
        newNextPage = (startIndex + limit).toString();
      }

      return { items: paginatedItems, nextPage: newNextPage };
    }

    async function listUserItems(
      type='all',
      options?: { limit?: number; nextPage?: string }
    ): Promise<CRUDL.QueryResponse> {
      const limit = options?.limit || 50;
      const startIndex = options?.nextPage ? parseInt(options.nextPage, 0) : 0;

      // Get all items from the store
      let allItemsInStore: CRUDL.Item[] = Array.from(items.value.values());

      let filteredItems: CRUDL.Item[];
      if (type && type !== 'all') {
        // Filter by type if provided and not 'all'
        filteredItems = allItemsInStore.filter(item => item.type === type);
      } else {
        // Otherwise, use all items (no type filter or type is 'all')
        filteredItems = allItemsInStore;
      }

      const paginatedItems = filteredItems.slice(startIndex, startIndex + limit);
      const newNextPage = (startIndex + limit < filteredItems.length) ? (startIndex + limit).toString() : undefined;

      // Using Promise.resolve as per example, though direct return of the object is also fine in async function
      return Promise.resolve({ items: paginatedItems, nextPage: newNextPage });
    }

    return {
      items,
      createItem,
      readItem,
      updateItem,
      deleteItem,
      listChildren,
      listUserItems
    }
  },
  {
    persist: {
      key: 'crudlLocal',
      storage: localStorage,
      serializer: {
        serialize: (state) => {
          return JSON.stringify(Array.from(state.items.entries()))
        },
        deserialize: (storedValue) => {
          try {
            const entries = JSON.parse(storedValue)
            return { items: new Map(entries) }
          } catch {
            return { items: new Map() }
          }
        }
      }
    },
  }
);
